#include <cstdio>
#include <algorithm>
using namespace std;
int dp[1010];
int main() {
    int T, M, t, v;
    scanf("%d%d", &T, &M);
    // dp[i][j]表示前i种草药在j时间内能获得的最大价值
    for (int i = 0; i < M; i++) {
        scanf("%d%d", &t, &v);
        for (int j = T; j >= t; j--) {
            dp[j] = max(dp[j], dp[j - t] + v);
        }
    }
    printf("%d\n", dp[T]);
    return 0;
}
